/* Factory-specific camera coverage, synchronized with the campus architectural view. */
const factoryCctv={camera:0,coverage:false,mode:'single'};
const factoryCameraLocations=[[[27,80],[48,30],[72,38],[76,68]],[[24,72],[49,22],[76,44],[79,58]],[[50,82],[42,28],[74,46],[79,67]],[[18,46],[47,28],[71,44],[73,70]]];
const factoryCameraAreas=[['Main entrance','Workforce Mgmt','Administration and gate'],['Production corridor','Process','Production observation corridor'],['Packaging hall','Packaging','Packaging and inspection'],['Warehouse / dispatch','Supply Chain','Storage and customer dispatch']];
function cameraFactory(){return state.factory>=0?state.factory:null}
function cameraRecord(fi,index){const spec=factoryCameraAreas[index],layout=completion.layouts?.[fi],mapped=layout?.points?.[spec[1]],position=saved.cameraPositions?.[fi+'-'+index]||(mapped?[mapped.x,mapped.y]:factoryCameraLocations[fi][index]);return {factory:fi,index,id:factoryCodes[fi]+'-CAM-0'+(index+1),name:spec[0],area:spec[1],coverage:spec[2],x:position[0],y:position[1],url:saved.cameras[fi+'-'+index]||'',architecture:architectureFor(fi)}}
function cameraVisual(fi,index,compact=false){const c=cameraRecord(fi,index),position=[0,33.333333,66.666667,100];return `<div class="factory-camera-frame ${compact?'camera-compact':''}" data-camera-id="${c.id}">${c.url?`<img class="factory-camera-source" src="${escapeHTML(c.url)}" alt="Configured image source: ${escapeHTML(c.name)}" referrerpolicy="no-referrer" onload="cameraImageState(this,true)" onerror="cameraImageState(this,false)">`:`<div class="factory-camera-art" role="img" aria-label="Illustrative ${escapeHTML(c.name)} matching ${escapeHTML(factories[fi].name)}" style="background-position:${position[index]}% ${position[fi]}%"></div>`}<div class="camera-frame-top"><span>${c.id}</span><span>${c.url?'IMAGE SOURCE':'ILLUSTRATIVE STILL'}</span></div><div class="camera-frame-bottom"><span>${escapeHTML(c.name)}</span><small>${c.url?'Image loading…':'Simulation · not live footage'}</small></div></div>`}
function cameraImageState(image,ok){const frame=image.closest('.factory-camera-frame');if(!frame)return;const state=frame.querySelector('.camera-frame-bottom small');state.textContent=ok?'Image loaded · streaming not enabled':'Source unavailable · check access or URL';frame.classList.toggle('camera-source-error',!ok);if(!ok)image.alt='Camera image unavailable. No simulated replacement is shown.'}
function cameraCampus(fi,small=false){const art=architectureFor(fi),layout=completion.layouts?.[fi];return `<div class="camera-campus ${small?'camera-campus-small':''}" data-camera-campus="${fi}"><img onload="cameraCampusLoaded(this)" src="${art.src}" alt="${escapeHTML(factories[fi].name)} campus camera coverage"><div class="camera-coverage-pins">${factoryCameraAreas.map((_,i)=>{const c=cameraRecord(fi,i);return `<button class="campus-camera-pin ${i===factoryCctv.camera?'selected':''}" style="left:${c.x}%;top:${c.y}%" onclick="selectFactoryCamera(${i})" aria-label="Select ${c.id} ${escapeHTML(c.name)}" title="${escapeHTML(c.name)}"><span>◉</span><b>0${i+1}</b></button>`}).join('')}</div><div class="camera-campus-caption">${layout?'Organization layout · camera positions require verification':'Illustrative camera positions · '+escapeHTML(art.style)}</div></div>`}
async function applyCameraLayout(){const fi=cameraFactory();if(fi==null)return;const layout=completion.layouts?.[fi];if(!layout)return;try{const entry=await fileStore('get',layout.id);if(!entry)return;const url=URL.createObjectURL(entry.file);let used=false;document.querySelectorAll(`[data-camera-campus="${fi}"]>img`).forEach(img=>{img.src=url;img.alt='Organization supplied site layout · '+layout.revision;used=true});if(!used)URL.revokeObjectURL(url);else {if(factoryCctv.layoutURL)URL.revokeObjectURL(factoryCctv.layoutURL);factoryCctv.layoutURL=url}}catch{}}
function selectFactoryCamera(index){if(!Number.isInteger(index)||index<0||index>3)return;factoryCctv.camera=index;op.camera=index;if($('#modal').open&&$('#modalbody .factory-cctv-modal'))cameraCenter(index);else render()}
function cameraChooser(){return `<section class="panel cctv-factory-chooser"><h2>Choose a factory for CCTV</h2><p>Camera views, source settings and mapped positions are kept separate for every site.</p><div class="entity-grid">${factories.map((f,fi)=>`<button class="entity" onclick="openFactoryCctv(${fi})"><img src="${architectureFor(fi).src}" alt="${escapeHTML(f.name)} 3D campus"><strong>${escapeHTML(f.name)}</strong><small>${escapeHTML(architectureFor(fi).style)}</small><span>4 mapped cameras →</span></button>`).join('')}</div></section>`}
function openFactoryCctv(fi){if(!Number.isInteger(fi)||!factories[fi])return;$('#modal').close();state.factory=fi;factoryCctv.camera=0;go('CCTV')}
function cctvWorkspace(modal=false){const fi=cameraFactory();if(fi==null)return cameraChooser();const selected=cameraRecord(fi,factoryCctv.camera),configured=factoryCameraAreas.filter((_,i)=>!!saved.cameras[fi+'-'+i]).length;return `<section class="panel factory-cctv-workspace ${modal?'factory-cctv-modal':''}"><div class="panelhead"><div><h2>${escapeHTML(factories[fi].name)} · CCTV</h2><small>${escapeHTML(architectureFor(fi).style)} · ${configured}/4 image sources configured</small></div><div class="actions">${opButton(factoryCctv.mode==='wall'?'Selected view':'Camera wall',"factoryCctv.mode=factoryCctv.mode==='wall'?'single':'wall';refreshCctvView()")}${opButton('Locate on campus','locateFactoryCamera()')}${opButton('Source settings','configureFactoryCamera()')}</div></div><div class="factory-cctv-layout"><aside class="camera-campus-panel"><h3>Campus camera coverage</h3>${cameraCampus(fi)}<div class="camera-location-note"><strong>${selected.id} · ${escapeHTML(selected.name)}</strong><small>${escapeHTML(selected.coverage)}</small><span>${selected.url?'Configured still-image endpoint':'Illustrative view · architectural reference only'}</span></div></aside><div class="camera-viewing-area">${factoryCctv.mode==='wall'?`<div class="factory-camera-wall">${factoryCameraAreas.map((_,i)=>`<button class="camera-wall-tile ${i===factoryCctv.camera?'selected':''}" onclick="factoryCctv.mode='single';selectFactoryCamera(${i})">${cameraVisual(fi,i,true)}</button>`).join('')}</div>`:`<div class="camera-selected-view">${cameraVisual(fi,factoryCctv.camera)}<div class="camera-selected-actions"><span>${escapeHTML(selected.coverage)}</span>${opButton('Refresh image','refreshCctvView()')}${opButton('Enlarge','enlargeFactoryCamera()')}</div></div>`}<div class="camera-thumbnails">${factoryCameraAreas.map((_,i)=>{const c=cameraRecord(fi,i);return `<button class="${i===factoryCctv.camera?'selected':''}" onclick="selectFactoryCamera(${i})">${cameraVisual(fi,i,true)}<strong>${c.id}</strong><small>${escapeHTML(c.name)}</small></button>`}).join('')}</div></div></div><div class="camera-workspace-notice">Illustrative views match each campus’s architectural identity; they are not surveyed camera footage. Real camera locations and source alignment must be verified for the site. CIP and PAT remain measurement-based.</div></section>`}
function refreshCctvView(){if($('#modal').open&&$('#modalbody .factory-cctv-modal'))cameraCenter(factoryCctv.camera);else render()}
cameraCenter=function(index=factoryCctv.camera){if(Number.isInteger(index)&&index>=0&&index<4)factoryCctv.camera=index;op.camera=factoryCctv.camera;if(cameraFactory()==null){openModal('Choose factory cameras',cameraChooser());return}openModal('Factory camera views',cctvWorkspace(true));$('#modal').classList.add('wide-modal','cctv-modal');applyCameraLayout()};
function configureFactoryCamera(){const fi=cameraFactory();if(fi==null){cameraCenter();return}const c=cameraRecord(fi,factoryCctv.camera);openModal(c.id+' · Image source',`<p>${escapeHTML(factories[fi].name)} · ${escapeHTML(c.name)}</p><label>HTTPS image snapshot URL<input id="camera-url" type="url" placeholder="https://camera.example/snapshot.jpg" value="${escapeHTML(c.url)}"></label><details class="camera-marker-editor"><summary>Adjust camera marker position</summary><label>X (% of layout)<input id="camera-x" type="number" min="0" max="100" value="${c.x}"></label><label>Y (% of layout)<input id="camera-y" type="number" min="0" max="100" value="${c.y}"></label>${opButton('Save position',`saveFactoryCameraPosition(${c.index})`)}</details><p>Use a still-image endpoint from your authorized camera gateway. Streaming and recording are not enabled. Do not embed credentials in the URL.</p><div class="actions">${opButton('Save source',`saveCamera(${c.index})`)}${opButton('Use illustrative view',`resetCamera(${c.index})`)}${opButton('Back to cameras','cameraCenter()')}</div><div id="camera-feedback" class="warning"></div>`)}
saveCamera=function(index){const fi=cameraFactory();if(fi==null||!Number.isInteger(index)||index<0||index>3)return;try{const u=new URL($('#camera-url').value);if(u.protocol!=='https:'||u.username||u.password)throw Error();saved.cameras[fi+'-'+index]=u.href;persist();render();cameraCenter(index)}catch{$('#camera-feedback').textContent='Enter a valid HTTPS image URL without embedded username or password.'}};
resetCamera=function(index){const fi=cameraFactory();if(fi==null||!Number.isInteger(index)||index<0||index>3)return;delete saved.cameras[fi+'-'+index];persist();render();cameraCenter(index)};
function locateFactoryCamera(){const fi=cameraFactory();if(fi==null)return;$('#modal').close();factoryCctv.coverage=true;factoryInterior=true;smartFactoryMode='rendered';smartArea=cameraRecord(fi,factoryCctv.camera).area;state.tab='Factory Overview';render()}
function enlargeFactoryCamera(){const fi=cameraFactory();if(fi==null)return;const c=cameraRecord(fi,factoryCctv.camera);openModal(c.id+' · '+escapeHTML(c.name),`<div class="camera-enlarged">${cameraVisual(fi,c.index)}</div><p class="scope-label">${escapeHTML(factories[fi].name)} · ${c.url?'Configured image snapshot':'Illustrative still — not live footage'}</p><div class="actions">${opButton('Return to cameras','cameraCenter()')}</div>`);$('#modal').classList.add('wide-modal','cctv-modal')}
function toggleFactoryCameraCoverage(){factoryCctv.coverage=!factoryCctv.coverage;if(factoryCctv.coverage)smartFactoryMode='rendered';render()}
function decorateFactoryCameras(){if(state.tab==='CCTV'){applyCameraLayout();return}if(state.tab!=='Factory Overview'||!factoryInterior)return;const viewer=$('#smart-campus-viewer'),options=$('.smart-view-options>div');if(options){const engineering=[...options.querySelectorAll('button')].find(b=>b.textContent.trim()==='Explore 3D');engineering?.setAttribute('onclick',"factoryCctv.coverage=false;smartFactoryMode='engineering';render()")}if(options&&!options.querySelector('.camera-coverage-toggle'))options.insertAdjacentHTML('beforeend',opButton(factoryCctv.coverage?'Business details':'CCTV coverage','toggleFactoryCameraCoverage()','camera-coverage-toggle '+(factoryCctv.coverage?'active':'')));if(!factoryCctv.coverage||!viewer)return;const scene=$('#smart-campus-scene');if(scene){const pins=document.createElement('div');pins.className='camera-coverage-pins campus-camera-overlay';pins.innerHTML=factoryCameraAreas.map((_,i)=>{const c=cameraRecord(factoryIndex(),i);return `<button class="campus-camera-pin ${factoryCctv.camera===i?'selected':''}" style="left:${c.x}%;top:${c.y}%" onclick="selectFactoryCamera(${i})" title="${escapeHTML(c.name)}"><span>◉</span><b>${c.id}</b></button>`}).join('');scene.appendChild(pins);scene.querySelectorAll('.smart-building-hotspot').forEach(el=>el.hidden=true)}const inspector=$('.smart-area-inspector');if(inspector){const fi=factoryIndex(),c=cameraRecord(fi,factoryCctv.camera);inspector.classList.add('camera-inspector');inspector.innerHTML=`<div class="row"><small>CAMPUS CAMERA</small><span class="pill">${c.url?'Image source':'Illustrative'}</span></div><h2>${escapeHTML(c.name)}</h2><p>${c.id} · ${escapeHTML(c.coverage)}</p>${cameraVisual(fi,c.index,true)}<div class="camera-inspector-select">${factoryCameraAreas.map((x,i)=>opButton('0'+(i+1)+' · '+escapeHTML(x[0]),`selectFactoryCamera(${i})`,i===factoryCctv.camera?'active':'')).join('')}</div><div class="actions">${opButton('Open CCTV workspace',"go('CCTV')")}${opButton('Source settings','configureFactoryCamera()')}</div><small class="camera-honesty">${c.url?'Image snapshots only; no streaming.':'Architectural illustration · not actual CCTV footage.'}</small>`}}
if(!tabs.includes('CCTV'))tabs.splice(tabs.indexOf('Factory Overview')+1,0,'CCTV');
const genericBeforeFactoryCctv=generic;generic=function(){return state.tab==='CCTV'?cctvWorkspace():genericBeforeFactoryCctv()};
const renderBeforeFactoryCctv=render;render=function(){document.body.classList.toggle('factory-cctv-mode',state.tab==='CCTV');$('#modal').classList.remove('cctv-modal');renderBeforeFactoryCctv();decorateFactoryCameras()};


function cameraCampusLoaded(image){if(image.naturalWidth&&image.naturalHeight)image.parentElement.style.setProperty('--camera-ratio',String(image.naturalWidth/image.naturalHeight))}
const factorySelectorBeforeCctv=$('#factory').onchange;$('#factory').onchange=function(event){if(state.tab==='CCTV'){state.factory=Number(event.target.value);factoryCctv.camera=0;render()}else factorySelectorBeforeCctv.call(this,event)};


function saveFactoryCameraPosition(index){const fi=cameraFactory(),x=Number($('#camera-x')?.value),y=Number($('#camera-y')?.value);if(fi==null||index<0||index>3)return;if(!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>100||y<0||y>100){$('#camera-feedback').textContent='Enter X/Y positions between 0 and 100.';return}saved.cameraPositions??={};saved.cameraPositions[fi+'-'+index]=[x,y];persist();render();cameraCenter(index)}


const areaBeforeCctv=chooseSmartArea;chooseSmartArea=function(id){factoryCctv.coverage=false;areaBeforeCctv(id)};
const layerBeforeCctv=chooseSmartLayer;chooseSmartLayer=function(layer){factoryCctv.coverage=false;layerBeforeCctv(layer)};
const locateAssetBeforeCctv=locateAsset;locateAsset=function(){factoryCctv.coverage=false;locateAssetBeforeCctv()};
render();
